// 実サービスと台帳を突合する。**検出するだけで、自動是正はしない。**
// 緊急対応で手動停止したアカウントをリコンサイラが復活させる事故を防ぐため。
// 是正は台帳への PR(または提案 PR)を通す。
//
// 入力: { scope: 'full' | 'high-risk' }
//   high-risk … 管理者権限と「退職者が生きている」だけを見る(日次)
//   full      … 全項目(週次)
// 設計: docs/design/08-safeguards.md#ドリフトフロー外変更への対応方針

const inp = $input.first()?.json ?? {};
const body = inp.body ?? inp;
const scope = body.scope === 'high-risk' ? 'high-risk' : 'full';
return [{ json: { scope, kind: 'members' } }];

// ユーザーごとの所属グループを引くための問い合わせを作る。
// HTTP ノードはアイテムごとに実行されるので、ループを書かずに済む。
const users = $input.all().map((i) => i.json).filter((u) => u && u.id);
if (users.length === 0) return [{ json: { __noUsers: true, url: null } }];
return users.map((u) => ({ json: {
  userId: u.id, username: u.username, enabled: u.enabled, email: u.email,
  url: `${$env.KEYCLOAK_URL}/admin/realms/${$env.KEYCLOAK_REALM}/users/${u.id}/groups`,
}}));

// 台帳と Keycloak を突合する。
// 所属グループの取得は「1ユーザー1リクエスト」で流れており、
// n8n の pairedItem で元の問い合わせを辿れる。

const scope = $('範囲を決める').first().json.scope;
const members = $('メンバーを読む').all().map((i) => i.json).filter((m) => m.desired);
// HTTP ノードはアイテムごとに実行されるため、このノードが複数回走り
// $('...').all() が重複を返すことがある。username で一意化しておく。
const seen = new Set();
const queries = $('所属照会を組み立てる').all().map((i) => i.json)
  .filter((q) => q.userId && !seen.has(q.username) && seen.add(q.username));

// 応答をユーザーごとにまとめる
const groupsByUser = {};
for (const q of queries) groupsByUser[q.username] = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const g = items[i].json;
  if (!g || !g.name) continue;
  const src = items[i].pairedItem;
  const idx = typeof src === 'number' ? src : (src?.item ?? 0);
  const q = queries[idx];
  if (q) groupsByUser[q.username].push(g.name);
}

const byId = {};
for (const m of members) byId[m.id] = m;

const findings = { critical: [], warning: [], info: [] };

for (const q of queries) {
  const m = byId[q.username];
  const groups = (groupsByUser[q.username] ?? []).sort();

  // 台帳に存在しない Keycloak ユーザー(フロー外で作られた可能性)
  if (!m) {
    findings.critical.push(`台帳にないユーザーが IdP に存在: ${q.username} (${q.email ?? '-'})`
      + `${q.enabled ? '' : ' ※停止済み'}`);
    continue;
  }

  // 退職・契約終了なのに有効なまま(最も危険)
  if (m.desired.status === 'left' && q.enabled) {
    findings.critical.push(`削除済みのはずのユーザーが有効: ${q.username}`
      + `(台帳の最終日 ${m.desired.left_at ?? '未設定'})`);
  }

  // 管理者グループの持ち主が台帳上 admin ではない
  if (groups.includes('admins') && m.desired.role !== 'admin') {
    findings.critical.push(`管理者グループに台帳外の所属: ${q.username}(台帳の役割は ${m.desired.role})`);
  }

  if (scope === 'high-risk') continue;

  // 台帳の記録と実際の所属の食い違い
  const recorded = [...(m.state?.grants?.idp ?? [])]
    .filter((g) => g.startsWith('group:')).map((g) => g.slice(6)).sort();
  const extra = groups.filter((g) => !recorded.includes(g));
  const missing = recorded.filter((g) => !groups.includes(g));
  if (extra.length) {
    findings.warning.push(`${q.username}: 台帳にない所属 [${extra.join(', ')}]`);
  }
  if (missing.length) {
    findings.warning.push(`${q.username}: 台帳にあるが実際には未所属 [${missing.join(', ')}]`);
  }
}

// 台帳では在籍なのに IdP にいない(プロビジョニング未完)
if (scope === 'full') {
  const known = new Set(queries.map((q) => q.username));
  for (const m of members) {
    if (m.desired.status === 'active' && !known.has(m.id)) {
      findings.warning.push(`台帳では在籍だが IdP にユーザーが無い: ${m.id}(未収束の可能性)`);
    }
  }
}

// 同じ指摘が複数回積まれることがあるので最後に一意化する
for (const k of Object.keys(findings)) findings[k] = [...new Set(findings[k])];

return [{ json: { scope, findings, checkedUsers: queries.length, checkedMembers: members.length } }];

// NetBox と PC 台帳を突合し、結果をまとめて通知内容にする。
const idp = $('IdP と突合する').first().json;
const findings = idp.findings;
const scope = idp.scope;
const pcs = $('PC台帳を読む').all().map((i) => i.json).filter((p) => p.state);

let devices = [];
if (scope === 'full') {
  const res = $input.first()?.json ?? {};
  devices = res.results ?? [];

  const byId = {};
  for (const d of devices) byId[d.id] = d;
  const ledgerIds = new Set(pcs.map((p) => p.state.netbox_device_id));

  for (const p of pcs) {
    const dev = byId[p.state.netbox_device_id];
    if (!dev) {
      findings.warning.push(`台帳にあるが NetBox に無い機器: ${p.id}`);
      continue;
    }
    if (dev.asset_tag && dev.asset_tag !== p.state.asset_no?.value) {
      findings.warning.push(`資産管理番号の食い違い: 台帳 ${p.state.asset_no?.value} / NetBox ${dev.asset_tag}`);
    }
  }
  for (const d of devices) {
    if (!ledgerIds.has(d.id)) {
      findings.warning.push(`NetBox にあるが台帳に無い機器: ${d.name}(資産番号 ${d.asset_tag ?? '-'})`);
    }
  }
}

for (const k of Object.keys(findings)) findings[k] = [...new Set(findings[k])];
const total = findings.critical.length + findings.warning.length;
const L = [];
const section = (title, lines) => {
  if (!lines.length) return;
  L.push(`■ ${title}(${lines.length} 件)`);
  lines.forEach((x) => L.push(`  - ${x}`));
  L.push('');
};

if (total === 0) {
  L.push(scope === 'high-risk'
    ? '高リスク項目の突合: 異常なし。'
    : '台帳と実サービスは一致しています。');
} else {
  L.push(`台帳と実サービスに ${total} 件の差異があります。`, '');
  section('至急の確認が必要', findings.critical);
  section('要確認', findings.warning);
  L.push('※ 自動では修正しません。緊急対応で手動停止した場合など、',
    '   自動で元に戻すと危険なためです。台帳への PR で是正してください。', '');
}

L.push('───────────────',
  `範囲: ${scope === 'high-risk' ? '高リスク項目のみ(日次)' : '全項目(週次)'}`,
  `対象: IdP ユーザー ${idp.checkedUsers} / 台帳メンバー ${idp.checkedMembers}`
  + (scope === 'full' ? ` / 機器 ${devices.length}` : ''),
  `実行: ${new Date().toISOString()}`);

const level = findings.critical.length ? 'escalation' : (total ? 'warn' : 'info');
return [{ json: {
  to: String($env.ADMIN_EMAILS ?? '').split(',').map((s) => s.trim()).filter(Boolean),
  level,
  subject: total === 0
    ? `整合性監査(${scope === 'high-risk' ? '日次' : '週次'}): 異常なし`
    : `整合性監査: ${total} 件の差異(至急 ${findings.critical.length} 件)`,
  body: L.join('\n'),
  __findings: findings,
  __total: total,
}}];

const r = $('レポートを組み立てる').first().json;
return [{ json: {
  ok: true, scope: $('範囲を決める').first().json.scope,
  differences: r.__total, critical: r.__findings.critical.length,
  subject: r.subject, body: r.body,
}}];
